mapper.select:
SELECT id, created_at, email, user_id, ip, user_agent, result
FROM login_logs

    AND created_at >= #{start}
    AND created_at < #{end}

        AND email LIKE CONCAT('%', , '%') ESCAPE '\\'

    AND ip LIKE #{ipPattern} ESCAPE '\\'
    AND result = #{result}

ORDER BY created_at DESC, id DESC
